package com.vynedam.stockai.service; import com.vynedam.stockai.dto.OperationsDtos.SupplierRequest; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.Supplier; import com.vynedam.stockai.repository.SupplierRepository; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class SupplierService{private final SupplierRepository repo;public SupplierService(SupplierRepository r){repo=r;}public List<Supplier>list(){return repo.findAll();}public Supplier get(String id){return repo.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Supplier not found"));}public Supplier create(SupplierRequest r){var s=new Supplier();do{s.code="SUP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();}while(repo.existsByCode(s.code));apply(s,r);return repo.save(s);}public Supplier update(String id,SupplierRequest r){var s=get(id);apply(s,r);return repo.save(s);}private void apply(Supplier s,SupplierRequest r){s.name=r.name();s.contactName=r.contactName();s.email=r.email();s.phone=r.phone();s.gstin=r.gstin();s.leadTimeDays=r.leadTimeDays()==null?0:r.leadTimeDays();}}
